/**
 * Generates lib/quiz-index.ts from the question bank.
 *
 * The bank is 2.2MB once bundled, and every client surface that only wanted a
 * count, a category or a domain was pulling all of it. This emits the metadata
 * those surfaces need, which is a fraction of the size, and leaves the question
 * text, options and explanations to be fetched for the one cert being drilled.
 *
 * Run via `npm run build:index`. tests/content-integrity.test.ts asserts the
 * generated file still matches the bank, so it cannot silently go stale.
 */
import { build } from 'esbuild';
import { writeFileSync, mkdtempSync, readFileSync, existsSync, mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

async function load(entry, name) {
  const out = join(mkdtempSync(join(tmpdir(), 'idx-')), `${name}.mjs`);
  await build({
    entryPoints: [entry],
    bundle: true,
    format: 'esm',
    platform: 'node',
    outfile: out,
    logLevel: 'error',
  });
  return import(out);
}

const { QUIZ_QUESTIONS } = await load('lib/playbook-quiz.ts', 'bank');
const { TOPIC_ARTICLES } = await load('lib/playbook-content.ts', 'articles');
const { GLOSSARY_TERMS } = await load('lib/playbook-glossary.ts', 'glossary');

const entries = QUIZ_QUESTIONS.map((q) => [
  q.id,
  q.certTags,
  q.category,
  q.topic,
  q.difficulty[0], // b | i | a
  q.objectives ?? [],
]);

const file = `/**
 * Generated by scripts/build-quiz-index.mjs. Do not edit by hand.
 *
 * Question metadata without the bodies: enough to count, filter and group by
 * cert, domain, category and difficulty, without shipping 2.2MB of question
 * text to render a number.
 */
import type { QuizDifficulty } from '@/types';

export interface QuizIndexEntry {
  id: string;
  certTags: string[];
  category: string;
  topic: string;
  difficulty: QuizDifficulty;
  objectives: string[];
}

const DIFFICULTY: Record<string, QuizDifficulty> = {
  b: 'beginner',
  i: 'intermediate',
  a: 'advanced',
};

type Row = [string, string[], string, string, string, string[]];

const ROWS: Row[] = ${JSON.stringify(entries)};

export const QUIZ_INDEX: QuizIndexEntry[] = ROWS.map(
  ([id, certTags, category, topic, d, objectives]) => ({
    id,
    certTags,
    category,
    topic,
    difficulty: DIFFICULTY[d],
    objectives,
  }),
);

export const QUIZ_TOTAL = QUIZ_INDEX.length;
`;

writeFileSync('lib/quiz-index.ts', file);
console.log(`wrote lib/quiz-index.ts, ${QUIZ_QUESTIONS.length} entries, ${(file.length / 1024).toFixed(0)}kB`);

// ── Article and glossary indexes ─────────────────────────────────────────────
// Same reasoning as the quiz bank: the browser renders one article and one
// glossary definition at a time, but was loading every body up front. The
// indexes carry what the lists and filters need; bodies come from the API.

const articleIndex = TOPIC_ARTICLES.map((a) => ({
  id: a.id,
  title: a.title,
  category: a.category,
  certTags: a.certTags,
  vocab: a.vocab ?? [],
}));

writeFileSync(
  'lib/article-index.ts',
  `/** Generated by scripts/build-quiz-index.mjs. Do not edit by hand. */
export interface ArticleIndexEntry {
  id: string;
  title: string;
  category: string;
  certTags: string[];
  vocab: string[];
}

export const ARTICLE_INDEX: ArticleIndexEntry[] = ${JSON.stringify(articleIndex, null, 0)};
`,
);

const glossaryIndex = GLOSSARY_TERMS.map((t) => ({
  term: t.term,
  category: t.category,
  certTags: t.certTags,
}));

writeFileSync(
  'lib/glossary-index.ts',
  `/** Generated by scripts/build-quiz-index.mjs. Do not edit by hand. */
export interface GlossaryIndexEntry {
  term: string;
  category: string;
  certTags: string[];
}

export const GLOSSARY_INDEX: GlossaryIndexEntry[] = ${JSON.stringify(glossaryIndex, null, 0)};
`,
);

console.log(
  `wrote lib/article-index.ts (${articleIndex.length}) and lib/glossary-index.ts (${glossaryIndex.length})`,
);

// ── Objective titles ─────────────────────────────────────────────────────────
// Pulled from the published blueprints in docs/cert-objectives, so the progress
// view can say "2.6 Analyze the evidence of an attack" rather than repeating
// the domain name on every row. The docs are the same source the questions are
// written against, which is what keeps the two in step.

const OBJECTIVE_DOCS = { SecAI: 'docs/cert-objectives/secai-cy001.md' };

const objectiveTitles = {};
for (const [certId, path] of Object.entries(OBJECTIVE_DOCS)) {
  if (!existsSync(path)) continue;
  const doc = readFileSync(path, 'utf8');
  for (const m of doc.matchAll(/^### (\d\.\d) (.+)$/gm)) {
    objectiveTitles[`${certId}:${m[1]}`] = m[2].trim();
  }
}

writeFileSync(
  'lib/objective-titles.ts',
  `/** Generated by scripts/build-quiz-index.mjs. Do not edit by hand. */
export const OBJECTIVE_TITLES: Record<string, string> = ${JSON.stringify(objectiveTitles, null, 2)};
`,
);

console.log(`wrote lib/objective-titles.ts (${Object.keys(objectiveTitles).length})`);

// ── Article bodies as static assets ─────────────────────────────────────────
// Articles are identical for every visitor and never change between deploys,
// which makes them a static file rather than a request. Serving them from an
// API route meant Next marked the response no-store, so every reader re-fetched
// every article they opened. As files under public/ they are cached by the CDN
// and the browser for free.

mkdirSync('public/content/articles', { recursive: true });
for (const a of TOPIC_ARTICLES) {
  writeFileSync(`public/content/articles/${a.id}.json`, JSON.stringify(a));
}
console.log(`wrote ${TOPIC_ARTICLES.length} article files to public/content/articles`);
